<script setup lang="ts">
import { computed, ref, watch, nextTick } from 'vue';
import UButton from '@nuxt/ui/components/Button.vue';
import UInput from '@nuxt/ui/components/Input.vue';
import USelect from '@nuxt/ui/components/Select.vue';
import UBadge from '@nuxt/ui/components/Badge.vue';
import { state, workspaceAction, date } from '../store';
import type { LocalTask } from '../../application/local-tasks';
const capacity = ref(16), remoteQueue = ref(0), order = ref('fifo'), busy = ref(false), archived = ref(false), detail = ref<LocalTask | null>(null), removing = ref(false);
let inspectTrigger: HTMLElement | null = null;
async function closeDetail() { detail.value = null; await nextTick(); (inspectTrigger?.isConnected ? inspectTrigger : document.getElementById('taskboard-title'))?.focus({ preventScroll: true }); }
const columns = [{ id: 'queued', title: 'Queued' }, { id: 'running', title: 'Running' }, { id: 'finished', title: 'Review & finished' }];
const visible = computed(() => (state.board?.tasks ?? []).filter(task => archived.value || !task.archived));
const tasksFor = (column: string) => visible.value.filter(task => column === 'finished' ? !['queued', 'running'].includes(task.status) : task.status === column);
watch(() => !!state.settings, value => { if (value && state.settings) { capacity.value = state.settings.board.queueCapacity; remoteQueue.value = state.settings.board.orchestratorQueue; order.value = state.settings.board.order; } }, { immediate: true });
watch(() => state.board?.tasks.find(task => task.id === detail.value?.id)?.status, async (value, previous) => { if (value && value !== previous && detail.value) { const id = detail.value.id; const result = await workspaceAction('/api/taskboard/detail', { id }); if (detail.value?.id === id) detail.value = result ?? null; } });
watch(() => state.unlocked, value => { if (!value) detail.value = null; });
async function action(body: { id: string; action: string; priority?: number }) { busy.value = true; try { const result = await workspaceAction('/api/taskboard/action', body); if (result && body.action === 'delete') await closeDetail(); else if (result && detail.value) detail.value = await workspaceAction('/api/taskboard/detail', { id: detail.value.id }) ?? null; } finally { busy.value = false; removing.value = false; } }
async function inspect(id: string, event: MouseEvent) { inspectTrigger = event.currentTarget as HTMLElement; detail.value = await workspaceAction('/api/taskboard/detail', { id }) ?? null; removing.value = false; await nextTick(); document.getElementById('local-task-detail')?.focus(); }
async function save() { busy.value = true; try { await workspaceAction('/api/settings', { board: { queueCapacity: capacity.value, orchestratorQueue: remoteQueue.value, order: order.value } }); } finally { busy.value = false; } }
function download() { if (!detail.value?.patch) return; const url = URL.createObjectURL(new Blob([detail.value.patch], { type: 'text/plain' })); const anchor = document.createElement('a'); anchor.href = url; anchor.download = 'werk-' + detail.value.id + '.patch'; anchor.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); }
</script>
<template>
<section v-if="state.unlocked" class="taskboard" aria-labelledby="taskboard-title"><div class="section-heading"><div><h2 id="taskboard-title" tabindex="-1">File tasks</h2><p class="page-note">Patch-producing tasks from Run task in Chat. Each owns a separate session and runs in this worker’s shared queue.</p></div><UButton color="neutral" variant="outline" :icon="state.settings?.board.paused ? 'i-lucide-play' : 'i-lucide-pause'" :disabled="busy" @click="workspaceAction('/api/settings', { board: { paused: !state.settings?.board.paused } })">{{ state.settings?.board.paused ? 'Resume intake' : 'Pause intake' }}</UButton></div>
<p v-if="state.board?.persistenceError" role="alert" class="error-text">A task result could not be saved. Check free disk space and state-directory permissions before restarting.</p>
<div v-if="state.settings?.board.paused" class="notice">Queue paused. The running task can finish; queued chat, file tasks and orchestrator assignments wait.</div>
<div class="board-columns"><section v-for="column in columns" :key="column.id" class="board-column"><h3>{{ column.title }} <span>{{ tasksFor(column.id).length }}</span></h3><p v-if="!tasksFor(column.id).length" class="board-empty">{{ column.id === 'queued' ? 'Ready for your next task' : column.id === 'running' ? 'No local task running' : 'Results appear here' }}</p><article v-for="task in tasksFor(column.id)" :key="task.id" class="task-card"><div class="actions"><UBadge :color="task.status === 'failed' ? 'error' : task.status === 'review' ? 'primary' : 'neutral'" variant="subtle">{{ task.status === 'review' ? 'Review patch' : task.status }}</UBadge><span v-if="task.priority === 2" class="muted">High priority</span></div><h4>{{ task.title }}</h4><p>{{ task.provider }} · {{ task.files.length }} {{ task.files.length === 1 ? 'file' : 'files' }}</p><UButton color="neutral" variant="outline" :aria-label="'Inspect local task ' + task.title" :aria-expanded="detail?.id === task.id" aria-controls="local-task-evidence" @click="inspect(task.id, $event)">Inspect task</UButton></article></section></div>
<label class="check-label"><input v-model="archived" type="checkbox"> Show archived tasks</label>
<section v-if="detail" id="local-task-evidence" class="evidence-panel"><div class="section-heading"><h3 id="local-task-detail" tabindex="-1">{{ detail.title }}</h3><UButton color="neutral" variant="ghost" aria-label="Close local task" icon="i-lucide-x" @click="closeDetail" /></div><p>{{ detail.status }} · {{ date(detail.createdAt) }} · {{ detail.provider }}</p><p>{{ detail.instruction }}</p><p v-if="detail.error" class="error-text">{{ detail.error }}</p><p v-if="detail.summary">{{ detail.summary }}</p><p class="break-anywhere">{{ detail.repository }}</p><ul><li v-for="file in detail.files" :key="file.path">{{ file.path }}</li></ul><div class="actions"><UButton v-if="['queued', 'running'].includes(detail.status)" color="neutral" variant="outline" :disabled="busy" @click="action({ id: detail.id, action: 'cancel' })">Stop task</UButton><UButton v-if="detail.status === 'queued'" color="neutral" variant="outline" :disabled="busy" @click="action({ id: detail.id, action: 'priority', priority: detail.priority === 2 ? 1 : 2 })">{{ detail.priority === 2 ? 'Normal priority' : 'Raise priority' }}</UButton><UButton v-if="['failed', 'cancelled'].includes(detail.status)" :disabled="busy" @click="action({ id: detail.id, action: 'retry' })">Retry saved input</UButton><UButton v-if="detail.patch" icon="i-lucide-download" @click="download">Download patch</UButton><template v-if="!['queued', 'running'].includes(detail.status)"><UButton color="neutral" variant="outline" :disabled="busy" @click="action({ id: detail.id, action: 'archive' })">{{ detail.archived ? 'Restore' : 'Archive' }}</UButton><UButton color="error" variant="ghost" @click="removing = !removing">Delete</UButton></template></div><div v-if="removing" class="confirm-row"><p>Delete the saved task and its board evidence?</p><UButton color="error" :disabled="busy" @click="action({ id: detail.id, action: 'delete' })">Confirm deletion</UButton></div><p v-if="detail.patch" class="page-note">Inspect this patch before applying it. Tests have not run. In your repository, use <code>git apply --check path/to/download.patch</code> before applying with <code>git apply</code>. Inputs were captured when this task was queued.</p><details v-if="detail.patch"><summary>Inspect patch</summary><pre>{{ detail.patch }}</pre></details></section>
<details class="monitor-section"><summary>Configure worker queue</summary><form class="settings-form" @submit.prevent="save"><div class="settings-grid"><div><label for="local-capacity">Chat + file-task capacity · queued + running</label><UInput id="local-capacity" v-model.number="capacity" type="number" min="1" max="64" required class="w-full" /></div><div><label for="remote-queue">Extra orchestrator queue places</label><UInput id="remote-queue" v-model.number="remoteQueue" type="number" min="0" max="64" required class="w-full" /></div><div><label for="queue-order">File-task start order</label><USelect id="queue-order" v-model="order" :items="[{ label: 'First in, first out', value: 'fifo' }, { label: 'High priority first', value: 'priority' }]" class="w-full" /></div></div><p class="page-note">This worker executes one task at a time across chat, file tasks and orchestrator assignments. Add more workers to run tasks in parallel. Extra queue places hold orchestrator assignments while their leases are renewed; lowering capacity keeps accepted work.</p><UButton type="submit" :loading="busy">Save queue settings</UButton></form></details>
<section v-if="state.status?.queuedTasks?.length" class="monitor-section"><h3>Waiting from the orchestrator</h3><ul class="profile-list"><li v-for="task in state.status.queuedTasks" :key="task.id"><div><strong>{{ task.id }}</strong><span>{{ task.profile }} · lease maintained</span></div></li></ul></section><p v-if="state.actionError" role="alert" class="error-text">{{ state.actionError }}</p>
</section>
</template>
